export enum AppState {
  LANDING = 'LANDING',
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  EDITING = 'EDITING',
  ERROR = 'ERROR'
}

export enum LayerType {
  BACKGROUND = 'background',
  OBJECT = 'object',
  TEXT = 'text',
  COMPOSITION = 'composition',
  GENERATED = 'generated'
}

export interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

export interface DetectedElement {
  label: string;
  category: LayerType;
  box_2d: number[]; // [ymin, xmin, ymax, xmax]
  visual_prompt: string;
  confidence?: number;
}

export interface Layer {
  id: string;
  name: string;
  type: LayerType;
  isVisible: boolean;
  box: BoundingBox; // Normalized 0-1000 coordinates
  imageSrc: string; // Base64 or Blob URL of the extracted cutout
  originalX: number; // Pixel coordinate on canvas
  originalY: number; // Pixel coordinate on canvas
  width: number; // Pixel width
  height: number; // Pixel height
  visual_prompt?: string;
  isGenerating?: boolean;
  isGenerated?: boolean;
  parentId?: string;
}

export interface ImageMetadata {
  width: number;
  height: number;
  src: string;
  file?: File; // Optional as it can't be stored in IndexedDB easily, we use src
}

export interface Project {
  id: string;
  name: string;
  timestamp: number;
  imageMetadata: ImageMetadata;
  layers: Layer[];
}

import { Project } from "../types";

const DB_NAME = "UnflattenAI_DB";
const STORE_NAME = "projects";
const DB_VERSION = 1;

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject("Error opening database");
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };
  });
};

export const saveProject = async (project: Project): Promise<void> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, "readwrite");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.put(project);

    request.onerror = () => reject("Error saving project");
    request.onsuccess = () => resolve();
  });
};

export const getProjects = async (): Promise<Project[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, "readonly");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onerror = () => reject("Error fetching projects");
    request.onsuccess = () => {
      const projects = request.result as Project[];
      resolve(projects.sort((a, b) => b.timestamp - a.timestamp));
    };
  });
};

export const deleteProject = async (id: string): Promise<void> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, "readwrite");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.delete(id);

    request.onerror = () => reject("Error deleting project");
    request.onsuccess = () => resolve();
  });
};

