    link.href = layer.imageSrc;
    link.download = `${layer.name.replace(/\s+/g, '_')}_${layer.isGenerated ? 'generated' : 'layer'}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

